"""
Cached Data Loader Module.
Loads analytical Parquet tables generated by Apache Spark and stored in Hadoop HDFS.
Supports fast caching and graceful fallback to synchronized Parquet tables.
"""

import os
import streamlit as st
import pandas as pd
from typing import List, Dict, Any, Optional

# List of the 12 analytical tables generated by Apache Spark
ANALYTICAL_TABLES = [
    "team_standings",
    "team_season",
    "team_h2h",
    "player_batting",
    "player_bowling",
    "player_potm",
    "season_summary",
    "phase_summary",
    "venue_summary",
    "team_venue",
    "toss_summary",
    "toss_season",
]


def get_available_tables() -> List[str]:
    """Returns the list of all available analytical tables."""
    return ANALYTICAL_TABLES.copy()


@st.cache_data(ttl=600, show_spinner="Loading analytical data from storage...")
def load_table(table_name: str) -> pd.DataFrame:
    """
    Loads an analytical table by name.
    
    Checks:
    1. Local synchronized Parquet cache at data/analytics/{table_name}
    2. HDFS via PySpark if spark session is active
    """
    if table_name not in ANALYTICAL_TABLES:
        raise ValueError(f"Unknown analytical table: '{table_name}'. Valid tables: {ANALYTICAL_TABLES}")

    # Primary fast path: Local Parquet mirror synced from HDFS
    local_path = os.path.join(os.path.dirname(__file__), f"../../data/analytics/{table_name}")
    if os.path.exists(local_path):
        try:
            return pd.read_parquet(local_path)
        except Exception as e:
            st.warning(f"Could not read local parquet cache for {table_name}: {e}")

    # Secondary path: Load from HDFS via PySpark
    try:
        from src.utils.spark_session import get_spark_session
        from src.ingestion.loader import get_default_hdfs_uri
        
        spark = get_spark_session("StreamlitDataLoader")
        hdfs_base = get_default_hdfs_uri()
        hdfs_path = f"{hdfs_base}/ipl/analytics/{table_name}"
        spark_df = spark.read.parquet(hdfs_path)
        return spark_df.toPandas()
    except Exception as e:
        raise RuntimeError(
            f"Failed to load table '{table_name}' from both HDFS and local Parquet mirror. Details: {e}"
        )


@st.cache_data(ttl=600)
def get_overall_kpis() -> Dict[str, Any]:
    """
    Computes high-level IPL tournament KPIs from the analytics tables.
    """
    season_df = load_table("season_summary")
    phase_df = load_table("phase_summary")
    teams_df = load_table("team_standings")
    batting_df = load_table("player_batting")
    bowling_df = load_table("player_bowling")

    total_matches = int(season_df["total_matches"].sum())
    total_seasons = int(len(season_df))
    total_runs = int(phase_df["total_runs"].sum())
    total_wickets = int(phase_df["total_wickets"].sum())
    total_teams = int(len(teams_df))
    total_fours = int(season_df["total_fours"].sum())
    total_sixes = int(season_df["total_sixes"].sum())
    
    top_run_scorer = batting_df.iloc[0]["batter"]
    top_runs = int(batting_df.iloc[0]["total_runs"])
    
    top_wicket_taker = bowling_df.iloc[0]["bowler"]
    top_wickets = int(bowling_df.iloc[0]["wickets"])
    
    top_team = teams_df.iloc[0]["team"]
    top_team_wins = int(teams_df.iloc[0]["wins"])

    return {
        "total_matches": total_matches,
        "total_seasons": total_seasons,
        "total_runs": total_runs,
        "total_wickets": total_wickets,
        "total_teams": total_teams,
        "total_fours": total_fours,
        "total_sixes": total_sixes,
        "top_run_scorer": top_run_scorer,
        "top_runs": top_runs,
        "top_wicket_taker": top_wicket_taker,
        "top_wickets": top_wickets,
        "top_team": top_team,
        "top_team_wins": top_team_wins,
    }


def get_table_metadata(table_name: str) -> Dict[str, Any]:
    """Returns row count, column list, and types for a given table."""
    df = load_table(table_name)
    return {
        "table_name": table_name,
        "row_count": len(df),
        "col_count": len(df.columns),
        "columns": list(df.columns),
        "dtypes": {col: str(dtype) for col, dtype in df.dtypes.items()},
    }
